'use strict';
function lifeState(){state.life??={autoAlarm:true,safeSeconds:0,weatherClock:0,weather:'clear',weatherIndex:0,weatherVisible:true,dog:null,horse:false,mounted:false,paving:false};return state.life}
function buildingWorkFactor(b){return ['drwal','mlyn'].includes(b.type)?1+.5*(Math.max(1,Math.min(3,b.level||1))-1):1}
function buildingUpgradeCost(b){const next=(b.level||1)+1;return {wood:20*next,stone:10*next}}
function upgradeVillageBuilding(x,y){const b=building(x,y);if(!b||!['dom','drwal','mlyn'].includes(b.type)||(b.level||1)>=3||Math.hypot(state.p.x/T-x-.5,state.p.y/T-y-.5)>7)return false;if((b.hp??buildingMaxHp(b))<buildingMaxHp(b)){say('Najpierw napraw budynek.');return false}const cost=buildingUpgradeCost(b);if(state.wood<cost.wood||state.stone<cost.stone){say('Brakuje surowców na ulepszenie.');return false}state.wood-=cost.wood;state.stone-=cost.stone;b.level=(b.level||1)+1;b.hp=buildingMaxHp(b);peopleSignature='';save();ui();renderLife(true);return true}
const lifeMaxHp=buildingMaxHp;buildingMaxHp=function(b){return lifeMaxHp(b)*(1+.25*(Math.max(1,Math.min(3,b.level||1))-1))};
const lifePathSpeed=pathSpeed;pathSpeed=function(x,y){const b=building(Math.floor(x/T),Math.floor(y/T));return b?.type==='sciezka'&&b.paved?1.8:lifePathSpeed(x,y)};
const lifeSetMode=setMode;setMode=function(m){lifeState().paving=false;lifeSetMode(m)};
function chooseStoneRoad(){setMode('sciezka');lifeState().paving=true;$('mode').textContent='Droga kamienna · 3 kamienia / pole';$('lifePanel').classList.add('hidden')}
const lifeBuild=build;build=function(x,y){if(mode!=='sciezka'||!lifeState().paving){lifeBuild(x,y);return}if(!state.settled||Math.hypot(state.p.x/T-x-.5,state.p.y/T-y-.5)>7){say('Załóż osadę i podejdź na 7 pól.');return}if(state.stone<3){say('Droga kamienna wymaga 3 kamienia na pole.');return}const existing=building(x,y);if(existing?.type==='sciezka'){if(existing.paved){say('Tutaj jest już kamienna droga.');return}existing.paved=true;state.stone-=3;save();ui();return}const count=state.buildings.length;lifeBuild(x,y);const b=building(x,y);if(state.buildings.length>count&&b?.type==='sciezka'){b.paved=true;state.stone-=2;save();ui()}};
const lifeConstructionHint=constructionHint;constructionHint=function(x,y,type=mode){if(type==='sciezka'&&lifeState().paving){const b=building(x,y);if(state.stone<3)return 'Brakuje kamienia: droga kosztuje 3 kamienia.';if(b?.type==='sciezka')return b.paved?'Tu już jest kamienna droga.':'Ulepsz ścieżkę · 3 kamienia.';const text=lifeConstructionHint(x,y,type);return text.startsWith('Możesz')?'Możesz budować · 3 kamienia · ruch +80%.':text}return lifeConstructionHint(x,y,type)};
const lifeDrawPath=drawPath;drawPath=function(b,x,y){lifeDrawPath(b,x,y);if(!b.paved)return;ctx.fillStyle='#aeb2a2';ctx.fillRect(x-12,y-12,24,24);for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]])if(building(b.x+dx,b.y+dy))ctx.fillRect(x+(dx<0?-24:dx>0?0:-12),y+(dy<0?-24:dy>0?0:-12),dx?24:24,dy?24:24);ctx.strokeStyle='#727d73';ctx.lineWidth=1;for(let i=-8;i<=8;i+=8){ctx.beginPath();ctx.moveTo(x-12,y+i);ctx.lineTo(x+12,y+i);ctx.stroke();ctx.beginPath();ctx.moveTo(x+i,y-12);ctx.lineTo(x+i,y+12);ctx.stroke()}};
function adoptDog(){const s=lifeState();if(s.dog||!state.settled||state.food<20)return false;state.food-=20;s.dog={x:state.p.x,y:state.p.y+15,path:[],wait:0};save();renderLife(true);return true}
function tameHorse(){const s=lifeState();if(s.horse||!ownCount('stajnia')||state.food<40||state.gold<30)return false;state.food-=40;state.gold-=30;s.horse=true;save();renderLife(true);return true}
function togglePlayerHorse(){const s=lifeState();if(!s.horse)return false;s.mounted=!s.mounted;save();renderLife(true);return true}
function playerTravelMultiplier(){return (state.buildings.some(b=>b.type==='stajnia')?1.5:1)*(state.life?.mounted?1.35:1)}
function updateLife(dt){const s=lifeState();if(villageProgress().alarm&&s.autoAlarm){const danger=state.war.raids.some(r=>!r.camp&&r.power>0)||state.towns.some(t=>t.relation==='war'&&t.raidTimer<=45);s.safeSeconds=danger?0:s.safeSeconds+dt;if(s.safeSeconds>=10){s.safeSeconds=0;setVillageAlarm(false);say('Zagrożenie minęło. Alarm zakończony — mieszkańcy wracają do pracy.')}}else s.safeSeconds=0;s.weatherClock+=dt;if(s.weatherClock>=60){s.weatherClock%=60;s.weatherIndex++;const pattern=seasonIndex()===3?['snow','fog','clear','snow']:['rain','clear','fog','clear'];s.weather=pattern[(s.weatherIndex-1)%pattern.length]}const dog=s.dog;if(dog){dog.wait-=dt;const d=Math.hypot(dog.x-state.p.x,dog.y-state.p.y);if(d>22&&!dog.path.length&&dog.wait<=0){const goal={x:Math.floor(state.p.x/T),y:Math.floor(state.p.y/T)},path=planUnitRoute(dog,goal);if(path!==undefined){dog.path=path||[];dog.wait=1}}if(d<=22){dog.path=[];cancelUnitRoute(dog)}if(dog.path.length){const p=dog.path[0];if(blocked(p.x,p.y)){dog.path=[];dog.wait=.2}else{const dx=p.x-dog.x,dy=p.y-dog.y,n=Math.hypot(dx,dy),step=170*dt;if(n<=step){dog.x=p.x;dog.y=p.y;dog.path.shift()}else{dog.x+=dx/n*step;dog.y+=dy/n*step}}}}}
const lifeStep=simulationStep;simulationStep=function(dt){lifeStep(dt);updateLife(dt)};
function drawLifeAnimals(){const s=lifeState(),d=s.dog;if(d&&seen.has(tileKey(Math.floor(d.x/T),Math.floor(d.y/T)))){const wag=Math.sin(state.time*7)*1.5;ctx.save();ctx.strokeStyle=(typeof dogCoat==='function'?dogCoat():'#a67b47');ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(d.x-8,d.y-6);ctx.lineTo(d.x-12,d.y-8.5+wag);ctx.lineTo(d.x-13,d.y-11.5+wag*.6);ctx.stroke();ctx.restore();ctx.fillStyle=(typeof dogCoat==='function'?dogCoat():'#a67b47');ctx.fillRect(d.x-9,d.y-8,18,9);ctx.fillRect(d.x+5,d.y-14,9,9);ctx.fillStyle='#4b3e2e';ctx.fillRect(d.x+12,d.y-12,3,3);drawWalkingLegs(d.x,d.y-1,d,'#6c5137',3,6);if(state.appearance?.dogName){ctx.font='11px system-ui';ctx.fillStyle='#f3e6bd';ctx.textAlign='center';ctx.fillText(state.appearance.dogName,d.x,d.y-23);ctx.textAlign='start'}}}
const lifeWorld=drawWarWorld;drawWarWorld=function(){lifeWorld();drawLifeAnimals()};
const lifeStructure=structure;structure=function(b,x,y){lifeStructure(b,x,y);if((b.level||1)>1){ctx.fillStyle='#f0d791';ctx.font='bold 11px system-ui';ctx.fillText('★ '+b.level,x-10,y-53)}};
const lifeDraw=draw;draw=function(){lifeDraw();const s=lifeState();if(!s.weatherVisible||s.weather==='clear')return;ctx.save();if(s.weather==='fog'){ctx.fillStyle='#dce5d32c';ctx.fillRect(0,0,innerWidth,innerHeight)}else{ctx.strokeStyle=s.weather==='snow'?'#f4f6e2bb':'#b9d9db77';ctx.lineWidth=s.weather==='snow'?3:1;ctx.beginPath();for(let i=0;i<65;i++){const x=(hash(i,37)*innerWidth+state.time*12)%innerWidth,y=(hash(i,83)*innerHeight+state.time*(s.weather==='snow'?22:150))%innerHeight;ctx.moveTo(x,y);ctx.lineTo(x+(s.weather==='snow'?1:-4),y+(s.weather==='snow'?2:12))}ctx.stroke()}ctx.restore()};
let lifeSignature='';function renderLife(force=false){if($('lifePanel').classList.contains('hidden'))return;const s=lifeState(),near=state.buildings.filter(b=>['dom','drwal','mlyn'].includes(b.type)&&Math.hypot(b.x+.5-state.p.x/T,b.y+.5-state.p.y/T)<=7),signature=JSON.stringify([s.autoAlarm,s.weather,s.weatherVisible,!!s.dog,s.horse,s.mounted,Math.floor(state.wood),Math.floor(state.stone),Math.floor(state.food),state.gold,near.map(b=>[b.x,b.y,b.level])]);if(!force&&signature===lifeSignature)return;lifeSignature=signature;const btn=(action,label,id='',disabled=false)=>`<button data-life="${action}" data-id="${id}" ${disabled?'disabled':''}>${label}</button>`;$('lifeContent').innerHTML='<h3>Alarm obronny</h3><p>Automatyczne zakończenie po 10 sekundach bez najazdu i ostrzeżenia o ataku w ciągu 45 sekund.</p>'+btn('alarm',s.autoAlarm?'✓ Automatyczny powrót do pracy':'Włącz automatyczny powrót')+'<h3>Ulepszenia · podejdź na 7 pól</h3><p>Dom: 3 / 5 / 7 mieszkańców. Chata drwala i młyn: wydajność 100% / 150% / 200%. Maksymalnie 3 poziomy.</p>'+near.map(b=>{const c=buildingUpgradeCost(b);return '<p>'+(defs.find(d=>d[0]===b.type)?.[2])+' · '+b.x+', '+b.y+' · poziom '+(b.level||1)+'</p>'+btn('upgrade',(b.level||1)>=3?'Maksymalny poziom':'Ulepsz · '+c.wood+' drewna, '+c.stone+' kamienia',b.x+':'+b.y,(b.level||1)>=3)}).join('')+'<h3>Drogi kamienne</h3><p>3 kamienia za pole lub ulepszenie ścieżki. Przyspieszają ruch o 80%. Buduj także przeciąganiem.</p>'+btn('road','Buduj drogę kamienną')+'<h3>Pogoda</h3><p>Teraz: '+({clear:'pogodnie',rain:'deszcz',snow:'śnieg',fog:'mgła'}[s.weather])+'. Zmienia się co minutę gry. Jest dekoracyjna.</p>'+btn('weather',s.weatherVisible?'Ukryj efekty pogody':'Pokaż efekty pogody')+'<h3>Zwierzęta</h3><p>Pies chodzi za ludkiem i omija przeszkody. Koń wymaga stajni i przyspiesza jazdę o 35%.</p>'+btn('dog',s.dog?'✓ Pies jest z Tobą':'Przygarnij psa · 20 żywności','',!!s.dog)+btn('horse',s.horse?'✓ Koń oswojony':'Oswój konia · 40 żywności, 30 monet','',s.horse||!ownCount('stajnia'))+btn('ride',s.mounted?'Zsiądź z konia':'Wsiądź na konia','',!s.horse)}
$('lifeOpen').onclick=()=>{$('lifePanel').classList.remove('hidden');renderLife(true)};$('lifeClose').onclick=()=>$('lifePanel').classList.add('hidden');$('lifeContent').onclick=e=>{const b=e.target.closest('[data-life]');if(!b)return;switch(b.dataset.life){case 'alarm':lifeState().autoAlarm=!lifeState().autoAlarm;save();renderLife(true);break;case 'upgrade':upgradeVillageBuilding(...b.dataset.id.split(':').map(Number));break;case 'road':chooseStoneRoad();break;case 'weather':lifeState().weatherVisible=!lifeState().weatherVisible;save();renderLife(true);break;case 'dog':adoptDog();break;case 'horse':tameHorse();break;case 'ride':togglePlayerHorse();break}};
const lifeUI=ui;ui=function(){lifeUI();renderLife()};
// Track actual displacement, not key presses, so walls and pauses stop the feet.
const walkStates=new WeakMap(),formationWalkers=new WeakMap();
function formationWalker(group,i){let units=formationWalkers.get(group);if(!units){units=[];formationWalkers.set(group,units)}return units[i]??(units[i]={})}
function walkingSwing(actor,x,y){if(!actor)return 0;let s=walkStates.get(actor);if(!s){s={x,y,time:state.time,phase:0,moving:false};walkStates.set(actor,s);return 0}if(s.time!==state.time){const d=Math.hypot(x-s.x,y-s.y);s.phase+=Math.min(d,20)*.22;s.moving=d>.05;s.x=x;s.y=y;s.time=state.time}return s.moving&&!state.clock?.paused?Math.sin(s.phase)*4:0}
function drawWalkingLegs(x,y,actor,color='#493e31',width=4,length=9){const swing=walkingSwing(actor?.walkSource||actor,x,y);ctx.strokeStyle=color;ctx.lineWidth=width;for(const sign of [-1,1]){const hip=x+sign*4,offset=swing*sign;ctx.beginPath();ctx.moveTo(hip,y);ctx.lineTo(hip+offset*.55,y+length*.5);ctx.lineTo(hip+offset,y+length-Math.abs(offset)*.3);ctx.stroke()}ctx.lineWidth=1}
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('lifePanel').classList.add('hidden')});lifeState();
